```javascript
const axios = require("axios");

async function getYoutubeOembed(videoUrl) {
  try {
    const response = await axios.get(
      "https://www.youtube.com/oembed",
      {
        params: {
          url: videoUrl,
          format: "json"
        }
      }
    );
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

async function uploadYoutubeLandingPage(videoUrl) {
  try {
    const response = await axios.post(
      "https://oo6o8y6la6.execute-api.eu-central-1.amazonaws.com/default/Upload-DownloadYoutubeLandingPage",
      {
        url: videoUrl,
        app: "transkriptor",
        is_only_download: true
      },
      {
        headers: {
          "Content-Type": "application/json"
        }
      }
    );
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

async function processVideo(videoUrl) {
  const oembedData = await getYoutubeOembed(videoUrl);
  if (oembedData.error) {
    return m.reply(`Error getting oembed data: ${oembedData.error}`);
  }

  const uploadResult = await uploadYoutubeLandingPage(videoUrl);
  if (uploadResult.error) {
    return m.reply(`Error uploading to landing page: ${uploadResult.error}`);
  }

  return {
    oembed: oembedData,
    upload: uploadResult
  };
}

const youtubeUrl = "https://youtu.be/M7y9sIvMGjw";

processVideo(youtubeUrl)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
